select c.name, s.metric,
       s.sheet_best_week, hs.lifetime_high as app_best_week, s.sheet_week, hs.achieved_week as app_week,
       case when hs.lifetime_high is null then 'NO RECORD IN APP'
            when hs.lifetime_high < s.sheet_best_week - 0.5 then 'APP LOWER'
            else 'ok' end as week_verdict,
       s.sheet_best_month, hs.lifetime_high_month as app_best_month, s.sheet_month, hs.achieved_month as app_month,
       case when s.sheet_best_month is null then '-'
            when hs.lifetime_high_month is null then 'NO RECORD IN APP'
            when hs.lifetime_high_month < s.sheet_best_month - 0.5 then 'APP LOWER'
            else 'ok' end as month_verdict
from sheet s
join myntmore.clients c on lower(c.name) like '%' || s.client_key || '%'
left join myntmore.high_scores hs on hs.client_id = c.id and hs.metric_id = s.metric
where hs.lifetime_high is null
   or hs.lifetime_high < s.sheet_best_week - 0.5
   or (s.sheet_best_month is not null and (hs.lifetime_high_month is null or hs.lifetime_high_month < s.sheet_best_month - 0.5))
order by c.name, s.metric;
